llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Propafenone, the highest-transfer analogue, has absolute oral bioavailability of 5% in a human subject after a 300 mg oral dose, showing that a secondary-amine aromatic drug can have F well below 20% due to extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "DMT, an indoleethylamine, has estimated absolute bioavailability of about 10–15% after oral administration, supporting low oral F for indole-containing basic amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Sumatriptan, an indole with a basic amine, has absolute oral bioavailability of 14% (10–26%) after a 100 mg oral dose, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Epanolol, a secondary-amine beta-blocker, has oral bioavailability of 7–8% in healthy volunteers under fasting conditions, attributed to first-pass hepatic extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Eluxadoline, a zwitterionic molecule with acidic and basic groups, has human oral bioavailability of 1.02% due to low GI permeability and hepatic first-pass extraction; the query's zwitterionic hydroxamic acid/secondary amine character is analogous.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Tadalafil, an indole-containing analogue, has oral bioavailability of at least 36% in humans, showing that an indole core alone does not force low F, but it lacks the query's ionizable zwitterionic pair.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted low (F < 20%) because the highest-transfer and most mechanistically relevant analogues—propafenone, DMT, sumatriptan, epanolol, and eluxadoline—all show low absolute oral bioavailability (1–15%) and share key features such as basic amines, indole/aromatic systems, and in eluxadoline's case zwitterionic acid/base character. The few high-F analogues are less transferable and lack the same ionization liability.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Metabolic stability and first-pass extraction of the hydroxamic acid moiety are unknown.",
    "Transporter-mediated efflux or absorption effects for the query have not been directly assessed.",
    "The query's very low neutral fraction at pH 7.4 is a physicochemical liability, but its quantitative impact on human F is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

